mapper.sql:
p.is_deleted = 0 and p.status = 1 and c.status = 1
and p.category_id = #{categoryId}
and c.name = #{categoryName}
and (p.name like concat('%', #{keyword}, '%') or p.brand_name like concat('%', #{keyword}, '%') or p.subtitle like concat('%', #{keyword}, '%'))

mapper.select:
select 
from product p
inner join category c on c.id = p.category_id

where p.category_id = #{categoryId}
  and p.id != #{excludeId}
  and p.status = 1
  and p.is_deleted = 0
  and c.status = 1
order by p.sort desc, p.id desc
limit #{limit}
